HEADERS = {
    "Authorization": f"Bearer {TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json"
}

def test_post_api_profiles_initial_profile_setup():
    url = f"{BASE_URL}/api/profiles"
    profile_data = {
        "display_name": "Test User",
        "role": "driver"
    }
    try:
        response = requests.post(url, json=profile_data, headers=HEADERS, timeout=30)
        assert response.status_code == 200, f"Expected status 200, got {response.status_code}"
        data = response.json()
        # Validate presence of expected fields in response 
        assert "id" in data, "Response JSON missing 'id'"
        assert data.get("display_name") == profile_data["display_name"], "display_name does not match"
        assert data.get("role") == profile_data["role"], "role does not match"
        # Optionally check other profile fields if present
    finally:
        # Cleanup: attempt to delete the created profile, if endpoint exists.
        # However, no DELETE endpoint specified for /api/profiles. So skipping cleanup.
        pass

test_post_api_profiles_initial_profile_setup()